RSpec.describe Timekeeping::LocalOwner do
  # "mark_billed bills only the entries the invoice holds by committed reservation."
  # "Each change writes version, audit, outbox and receipt in one transaction."
  it "local owner mark_billed bills once, and its replay returns the stored answer without a second version, audit or outbox row" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 60.0, note: "", bill_status: "unbilled"
    )
    actor = described_class::Actor.service(
      name: "invoice-boundary", company_id: company.id,
      operations: %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]
    )
    reservation_id = SecureRandom.uuid
    call = lambda do |operation, body, extra = {}|
      described_class.call(operation:, company_id: company.id, generation: generation.to_s, actor:,
                           params: { "body" => body.merge("generation" => generation) }.merge(extra))
    end
    call.call(:prepare, { "invoice_id" => 501, "operation_id" => reservation_id, "disposition" => "active", "entries" => [entry.id] })
    call.call(:commit, { "invoice_id" => 501, "operation_id" => reservation_id })
    version_before = entry.reload.version
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table} WHERE company_id = #{company.id}").to_i }
    counts_before = %w[entry_audits entry_outbox_items service_idempotency_receipts].index_with { |table| count.call(table) }
    command_body = { "operation_id" => SecureRandom.uuid }

    first = call.call(:mark_billed, command_body, "invoice_id" => 501)
    after_first = %w[entry_audits entry_outbox_items service_idempotency_receipts].index_with { |table| count.call(table) }
    replay = call.call(:mark_billed, command_body, "invoice_id" => 501)

    expect([first.status, first.body]).to eq([200, { "billed" => 1 }])
    expect([replay.status, replay.body]).to eq([200, { "billed" => 1 }])
    expect(entry.reload.bill_status).to eq("billed")
    expect(entry.version).to eq(version_before + 1)
    expect(after_first).to eq(counts_before.transform_values { |value| value + 1 })
    expect(%w[entry_audits entry_outbox_items service_idempotency_receipts].index_with { |table| count.call(table) })
      .to eq(after_first)
  end
end

