RSpec.describe Timekeeping::LocalOwner do
  # "mark_billed bills only the entries the invoice holds by committed reservation."
  # "Each change writes version, audit, outbox and receipt in one transaction."
  it "local mark_billed bills only committed entries of the invoice and a zero-entry answer replays as the same Hash" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    committed, provisional, other_invoice, unreserved = Array.new(4) do
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
        duration: 60.0, note: "", bill_status: "unbilled"
      )
    end
    [[committed, 501, "committed"], [provisional, 501, "provisional"], [other_invoice, 502, "committed"]].each do |entry, invoice_id, state|
      ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, company.id, entry.id, invoice_id, SecureRandom.uuid, state]))
        INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
        VALUES (?, ?, ?, ?, ?, 'active', NOW())
      SQL
    end
    actor = described_class::Actor.service(
      name: "invoice-boundary", company_id: company.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS
    )
    mark_billed = lambda do |invoice_id, key|
      described_class.call(operation: :mark_billed, company_id: company.id, generation:, actor:,
                           params: { "invoice_id" => invoice_id, "body" => { "generation" => generation, "operation_id" => key } })
    end
    versions = [committed, provisional, other_invoice, unreserved].to_h { |entry| [entry.id, entry.reload.version] }

    outcome = mark_billed.call(501, SecureRandom.uuid)

    expect([outcome.status, outcome.body]).to eq([200, { "billed" => 1 }])
    expect([committed, provisional, other_invoice, unreserved].map { |entry| entry.reload.bill_status })
      .to eq(%w[billed unbilled unbilled unbilled])
    expect(committed.reload.version).to eq(versions[committed.id] + 1)
    expect([provisional, other_invoice, unreserved].map { |entry| entry.reload.version })
      .to eq([provisional, other_invoice, unreserved].map { |entry| versions[entry.id] })
    expect(Timekeeping::LocalOutboxEntry.where(entry_id: committed.id).count).to eq(1)
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM entry_audits WHERE entry_id = #{committed.id}").to_i).to eq(1)

    empty_key = SecureRandom.uuid
    first = mark_billed.call(503, empty_key)
    receipts_after_first = ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i
    replay = mark_billed.call(503, empty_key)

    expect([first.status, first.body]).to eq([200, { "billed" => 0 }])
    expect(receipts_after_first).to eq(2)
    expect(replay.body).to be_a(Hash)
    expect([replay.status, replay.body]).to eq([200, { "billed" => 0 }])
    expect(ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM service_idempotency_receipts").to_i).to eq(2)
  end
end

