                                         "disposition" => "active", "entries" => entry_ids }).status).to eq(200)
      expect(call_owner.call(:commit, { "invoice_id" => 501, "operation_id" => operation_id }).status).to eq(200)
    end
    commit_set.call([first_entry.id])
    mark_billed_key = SecureRandom.uuid

    first = call_owner.call(:mark_billed, { "operation_id" => mark_billed_key }, { "invoice_id" => 501 })
