RSpec.describe Timekeeping::LocalOwner, "service command atomicity and receipt scope" do
  def service_command_spec_entry(company, agent_id: nil)
    user = create(:user)
    project = create(:project, client: create(:client, company:))
    Timekeeping::LocalEntry.create!(company_id: company.id, user_id: user.id, project_id: project.id,
                                    work_date: Date.current, duration: 60.0, note: "", bill_status: "unbilled", agent_id:)
  end

  def service_command_spec_actor(company, name)
    described_class::Actor.service(name:, company_id: company.id, operations: TimekeepingRules::EntryRules::BACKGROUND_OPERATIONS)
  end

  before { TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil) }

  let(:generation) { TimekeepingOwnership.current.generation }

  # "A failure injected after the reservation write leaves no reservation, operation, outbox row or receipt"
  it "a failure at outbox_written that the caller rescues inside its own transaction leaves no change, audit, outbox row or receipt" do
    company = create(:company)
    entry = service_command_spec_entry(company, agent_id: 77)
    stored_before = entry.reload.attributes.values_at("agent_id", "version")
    tables = %w[entry_audits entry_outbox_items service_idempotency_receipts]
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    before = tables.index_with { |table| count.call(table) }
    reached = []
    checkpoint = lambda do |step|
      reached << step
      raise ActiveRecord::RecordNotUnique, "injected" if step == :outbox_written
    end

    ApplicationRecord.transaction do
      described_class.call(operation: :detach_entries, company_id: company.id, generation:,
                           actor: service_command_spec_actor(company, "agent-destroy"), checkpoint:,
                           params: { "agent_id" => 77, "body" => { "operation_id" => SecureRandom.uuid } })
    rescue ActiveRecord::RecordNotUnique
      nil
    end

    expect(described_class::STEPS).to include(:outbox_written)
    expect(reached.count(:outbox_written)).to eq(1)
    expect(entry.reload.attributes.values_at("agent_id", "version")).to eq(stored_before)
    expect(tables.index_with { |table| count.call(table) }).to eq(before)
  end

  # "The same operation_id from two services, or from two companies, gives separate receipts"
  it "the same operation_id from two services of one company gives two receipts, each answering its own command" do
    company = create(:company)
    service_command_spec_entry(company, agent_id: 77)
    key = SecureRandom.uuid
    answers = %w[agent-destroy agent-cleanup].map do |name|
      described_class.call(operation: :detach_entries, company_id: company.id, generation:,
                           actor: service_command_spec_actor(company, name),
                           params: { "agent_id" => 77, "body" => { "operation_id" => key } })
    end

    expect(answers.map(&:body)).to eq([{ "detached" => 1 }, { "detached" => 0 }])
    expect(ActiveRecord::Base.connection.select_values(
      ActiveRecord::Base.sanitize_sql_array(["SELECT actor_name FROM service_idempotency_receipts WHERE key = ? ORDER BY id", key])
    )).to eq(%w[agent-destroy agent-cleanup])
  end
end
